/* ===== 09 demo: SYNTHETIC DEMONSTRATION DATA. Fictional people, places and events. Never merged with a real case. ===== */
const DEMO_LABEL = 'SYNTHETIC DEMONSTRATION DATA';
const DEMO = {
  case: { name: 'Depot incident review (synthetic)', number: 'DEMO/2026/001', type: 'Criminal', jurisdiction: 'Demonstration', court: 'Fictional Demonstration Tribunal', description: 'Fictional case used to demonstrate source tracing, potential-conflict surfacing and human review. All people, places and events are invented.' },
  docs: [
    { filename: 'PW-3 Statement.txt', category: 'Witness Statement', text: 'Statement of PW-3 recorded on 14 March 2026.\n\nI am a security guard employed at the Northgate Depot. On the evening in question I was on duty near Location A from about 8 PM.\n\nI saw Person A near Location A at approximately 9:30 PM. Person A was carrying a blue bag and walked away from the loading bay. I did not speak to Person A.\n\nI reported the matter to the supervisor at 9:50 PM.\f I have been shown Exhibit P-4 and I identify the bag as the one I saw. I noted the time in the depot log at 9:35 PM.' },
    { filename: 'CCTV Review Report.txt', category: 'CCTV Report', text: 'CCTV review report for Camera 2 at the Northgate Depot.\n\nCamera 2 covers the approach to Location A. The recording shows a person matching the description of Person A near Location A at 9:31 PM.\n\nThe camera clock was compared with the depot clock and an offset of about two minutes was noted. Exhibit P-2 is the exported footage.' },
    { filename: 'Device Location Record.txt', category: 'Phone / Digital Record', text: 'Device location record for a handset registered to Person A.\n\nThe network log places the handset registered to Person A in Location B between 9:15 PM and 9:50 PM. The record notes an accuracy radius of several hundred metres.\n\nThe extraction was performed by the cyber unit on 16 March 2026. Custody documentation is attached as Exhibit P-7.' },
    { filename: 'Incident Report.txt', category: 'Investigation Report', text: 'Incident report for the Northgate Depot.\n\nThe incident was reported to the depot supervisor at 9:50 PM. Person A was identified by PW-3 as the person near Location A. The supervisor recorded that Person A left Location A at about 9:40 PM.\n\nA photograph of the bag was taken and is marked Exhibit P-4.' },
    { filename: 'PW-5 Statement.txt', category: 'Witness Statement', text: 'Statement of PW-5 recorded on 15 March 2026.\n\nI work at the depot canteen. I saw Person A inside the canteen near Location C at about 9:20 PM. I cannot remember the exact time.' },
    { filename: 'Written Submission.txt', category: 'Written Submission', text: 'Written submission on behalf of the prosecution.\n\nIt is submitted that the identification of Person A near Location A is corroborated by independent surveillance records [1] Corroboration of Witness Accounts by Independent Records, paragraph 1. The location data relied on by the defence is to be read with its accuracy radius, see [2] Reliability and Context of Digital Location Records, paragraph 2.\n\nThe court has held that approximate recollection of time is fatal to a witness account [3] Imaginary Authority Z, paragraph 5.\n\nIt is submitted that, as a proposition of law, a disagreement between two records on location always means that the record later in time must be preferred.' },
  ],
  transcript: { filename: 'Hearing 3 transcript.txt', hearingDate: '2026-03-20', hearingNumber: '3', text: '10:02:10 Judge: Proceed with the examination of PW-3.\n10:04:41 Counsel (Prosecution): Where were you at 9:30 PM on the date in question?\n10:06:18 PW-3: I saw Person A near Location A at around 9:30 PM.\n10:07:30 Counsel (Defence): Did you speak to Person A?\n10:07:52 PW-3: No, I did not speak to Person A. I was near Location A the whole time.\n10:09:12 PW-3: I cannot remember the exact time. It was about 9:30 PM, perhaps a few minutes either way.\n10:11:05 Counsel (Defence): Is it correct that the handset registered to Person A was recorded in Location B at that time?\n10:12:20 PW-3: I do not know about the handset. I only know what I saw near Location A.\n10:14:33 PW-5: I saw Person A inside the canteen near Location C at about 9:20 PM.\n10:16:40 Judge: The record will reflect the submissions on the location data.\n10:18:02 Counsel (Prosecution): The prosecution submits that DEMO-001, paragraph 1 supports corroboration of the identification.' },
};
function createDemoCase(userId) {
  if (!AuthSvc.list(userId).length) TEST_AUTHORITIES.forEach(a => AuthSvc.add(userId, { title: a.title, citation: a.citation, court: a.court, year: a.year, kind: 'Judgment', keywords: a.topics, text: a.paras.join('\n\n') }));
  const C = CaseSvc.create(userId, DEMO.case, true);
  DEMO.docs.forEach(d => DocSvc.add(userId, C.id, { ...d, synthetic: true, size: d.text.length }));
  DocSvc.add(userId, C.id, { kind: 'transcript', ...DEMO.transcript, synthetic: true, size: DEMO.transcript.text.length });
  return C;
}
